"""Original abdominal examination: organ identification, fluid and venous signs."""
from qbank_authoring import question,ref
rows=[]
AB=ref('Clinical Methods: abdominal inspection, auscultation, palpation and percussion','https://www.ncbi.nlm.nih.gov/books/NBK420/')
SP=ref('Clinical Methods: spleen examination','https://www.ncbi.nlm.nih.gov/books/NBK258/')
AS=ref('Stanford Medicine 25: ascites and venous patterns','https://stanfordmedicine25.stanford.edu/the25/avp.html')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('In a patient with marked emphysema, the liver edge is palpable well below the costal margin. Which additional bedside assessment helps distinguish true enlargement from downward displacement?', 'Estimate both upper and lower borders to assess liver span',[
 ('Use the lower edge position alone as a definitive size measurement','A displaced diaphragm can move the whole liver downward.'),('Assume emphysema prevents hepatomegaly from any other cause','Coexisting liver disease remains possible.'),('Use splenic percussion as a direct liver-size measure','It assesses a different organ region.')],
 'Position and size are different properties','**A low liver edge does not by itself establish an increased span.**',['Thoracic hyperinflation can depress the diaphragm.','Body habitus and examination technique affect border detection.'],'**Confirm uncertain enlargement with imaging when clinically relevant.**',['Assess consistency, tenderness and associated disease signs.','Do not infer synthetic function from edge position.'],[['Low edge','Displacement or enlargement'],['Span','Upper-to-lower extent'],['Confirmation','Imaging if needed']],[AB],style='clinical_scenario')

q('A firm irregular nodular liver edge is palpated in a patient with weight loss. Which conclusion is appropriate?', 'Significant structural liver disease is possible, but examination alone cannot distinguish cirrhosis from malignancy reliably',[
 ('Nodularity uniquely identifies cirrhosis','Malignancy and other structural processes can produce irregularity.'),('The edge directly measures portal pressure','It does not quantify hemodynamics.'),('A palpable liver proves liver failure','Size and surface do not determine synthetic function by themselves.')],
 'Surface texture suggests a structural question','**Consistency and contour complement size and systemic findings.**',['Look for chronic-liver stigmata, ascites, nodes and other signs.','Laboratory injury and synthetic-function measures answer different questions.'],'**Use imaging and selected tissue assessment to establish the cause.**',['Do not diagnose a malignancy subtype by palpation.','Assess urgency from the whole presentation.'],[['Texture','Structural clue'],['Etiology','Requires confirmation'],['Function','Separate assessment']],[AB],style='clinical_scenario')

q('A tender enlarged liver shows expansile systolic pulsation with a high JVP and giant venous systolic waves. Which mechanism is favored?', 'Hepatic venous congestion from tricuspid regurgitation',[
 ('Acute hepatitis as uniquely established by tenderness','Tenderness is nonspecific and does not explain the systolic venous reflux pattern.'),('Aortic regurgitation as the direct hepatic-vein mechanism','The systemic venous signs more specifically support TR.'),('Isolated portal-vein obstruction without right-heart pressure effects','This does not explain the complete jugular/hepatic systolic pattern.')],
 'Timing links the abdominal and cardiovascular examinations','**TR can transmit RV systolic pressure backward through the venous system.**',['Differentiate true expansile pulsation from transmitted movement.','Congestion can cause tenderness and abnormal liver tests.'],'**Assess the valve, RV and cause of venous hypertension.**',['Use echo and appropriate liver assessment.','Do not label all painful hepatomegaly as primary hepatitis.'],[['Liver','Systolic expansion'],['JVP','Large v/cv waves'],['Mechanism','Right-sided regurgitant congestion']],[AB,ref('Clinical Methods: systolic murmurs','https://www.ncbi.nlm.nih.gov/books/NBK345/')],style='clinical_scenario')

q('Which combination favors an enlarged spleen over an enlarged left kidney?', 'A palpable notch, inferomedial movement with inspiration and inability to get above the mass',[
 ('A ballotable mass with a resonant colonic band anteriorly','This more strongly suggests a renal origin.'),('A mass confined to the pelvis without respiratory movement','This suggests a different origin.'),('An expansile midline pulsation','This raises a vascular rather than splenic question.')],
 'Identify the organ through several anatomical features','**An enlarged spleen typically descends inferomedially.**',['A notch is useful when present but may not be palpable.','No single feature has perfect accuracy.'],'**Use ultrasound when organ identity remains uncertain.**',['Begin palpation sufficiently low to avoid missing massive enlargement.','Handle gently, especially when the spleen may be fragile.'],[['Spleen','Notch/inspiratory descent'],['Kidney','Ballotability/possible anterior resonance'],['Uncertainty','Imaging']],[SP])

q('Why should splenic palpation begin in the right lower abdomen rather than immediately under the left costal margin?', 'A massively enlarged spleen can extend far inferomedially and its edge may otherwise be missed',[
 ('The normal spleen lies in the right iliac fossa','It does not.'),('The maneuver directly measures portal pressure','It identifies an edge rather than a pressure.'),('Deep forceful palpation is required to rupture the capsule for diagnosis','This is unsafe and unnecessary.')],
 'Search for the edge along the expected enlargement path','**Large organs can extend beyond the examiner’s initial search area.**',['Advance gently toward the left upper quadrant during inspiration.','Use position changes and bimanual technique as appropriate.'],'**Document size and associated findings without excessive pressure.**',['Assess nodes, liver and blood-count clues.','Confirm and investigate clinically significant enlargement.'],[['Starting point','Low and right'],['Direction','Toward left upper quadrant'],['Safety','Gentle technique']],[SP])

q('A spleen extends into the right lower abdomen. Which diagnostic group is particularly important in the differential?', 'Myeloproliferative disease and selected chronic infections among causes of massive splenomegaly',[
 ('Uncomplicated acute cystitis as the usual explanation','This does not usually produce massive splenic enlargement.'),('A normal variant requiring no assessment','This degree of enlargement warrants investigation.'),('A diagnosis of cirrhosis as certain from spleen size alone','Portal hypertension is possible, but massive size has a broader differential.')],
 'The degree of enlargement changes the differential','**CML, myelofibrosis and selected endemic infections can cause very large spleens.**',['Exposure geography, blood film and systemic findings guide the workup.','No size category uniquely identifies one disease.'],'**Assess blood counts, smear, imaging and targeted causes.**',['Consider symptoms of infarction, rupture risk and hypersplenism.','Avoid unnecessary trauma to the enlarged organ.'],[['Massive enlargement','Myeloproliferative/infectious differential'],['Context','Geography and blood findings'],['Diagnosis','Cause-specific testing']],[SP],style='clinical_scenario')

q('Flank dullness becomes resonant after the patient turns and fluid redistributes. What does this support?', 'Free intraperitoneal fluid causing shifting dullness',[
 ('A fixed solid retroperitoneal mass as the most likely mechanism','A solid mass does not redistribute with position in this way.'),('A specific diagnosis of cirrhotic ascites','The sign indicates fluid but not its etiology.'),('A measurement of the serum–ascites albumin gradient','That requires fluid and serum chemistry.')],
 'Position changes test whether a dull region can move','**Mobile fluid becomes dependent while gas-containing bowel rises.**',['Small or loculated collections may not show the classic pattern.','Obesity and technique affect accuracy.'],'**Use ultrasound to confirm and guide the next step.**',['New clinically significant ascites often requires diagnostic fluid assessment.','Do not infer infection status from percussion.'],[['Finding','Position-dependent dullness'],['Supports','Free fluid'],['Does not define','Cause or chemistry']],[AS],style='clinical_scenario')

q('Why is a hand placed firmly along the abdominal midline during a fluid-wave test?', 'To reduce transmission through the abdominal wall and improve interpretation of a fluid impulse',[
 ('To block portal venous blood flow','That is not the purpose.'),('To make all superficial fat waves prove ascites','The maneuver aims to reduce this false transmission.'),('To measure intra-abdominal pressure directly','A fluid-wave test is not a pressure measurement.')],
 'Control the route of the transmitted impulse','**Abdominal-wall transmission can mimic a fluid wave.**',['A fluid impulse is more likely with larger free-fluid volumes.','A negative test does not exclude a smaller collection.'],'**Combine with shifting dullness and ultrasound.**',['Ensure the maneuver is comfortable.','Avoid treating one positive wave as an etiological diagnosis.'],[['Potential artifact','Wall/fat transmission'],['Midline pressure','Dampens that pathway'],['Confirmation','Other signs/imaging']],[AS])

q('A patient has abdominal distension but no detectable shifting dullness. Which conclusion is correct?', 'Small or loculated ascites remains possible; examination alone does not exclude it',[
 ('Any ascites is excluded by a negative test','Sensitivity depends on fluid amount and distribution.'),('The distension must be caused by obesity','Gas, masses, organ enlargement and fluid remain possibilities.'),('A negative test establishes normal portal pressure','It does not measure portal pressure.')],
 'A negative sign changes probability rather than guaranteeing absence','**Physical detection has volume and technical limits.**',['Loculation can prevent free movement.','The rest of the examination and history guide the next test.'],'**Use ultrasound if the fluid question matters clinically.**',['Assess gas, mass and organ causes as alternatives.','Do not perform blind invasive procedures from uncertain surface findings.'],[['Negative shifting','Does not exclude all fluid'],['Loculation','Can alter pattern'],['Next test','Ultrasound']],[AS],style='clinical_scenario')

q('Dilated superficial veins radiate from the umbilicus with flow away from it. Which mechanism is suggested?', 'Portal-hypertensive paraumbilical collateral flow',[
 ('IVC obstruction with the usual generalized upward collateral pattern','That has a different typical flow distribution.'),('A diagnosis of a specific cirrhosis etiology','The collateral pattern does not identify the cause of portal hypertension.'),('A normal arterial pulse pattern','These are venous collateral findings.')],
 'Flow direction adds information to vein appearance','**Paraumbilical collateral pathways can decompress the portal system.**',['Assess the pattern rather than calling every visible vein caput medusae.','IVC or other venous obstruction creates different pathways.'],'**Investigate the portal and systemic venous context.**',['Look for ascites, splenomegaly and liver findings.','Use imaging to define anatomy and cause.'],[['Umbilical radial flow','Portal collateral clue'],['Upward abdominal flow','Possible IVC obstruction'],['Etiology','Needs assessment']],[AS])

q('A patient with ascites has high JVP, an abdominojugular response and peripheral edema. Which cause deserves particular consideration?', 'Cardiac venous congestion, including right-heart failure or constrictive disease',[
 ('Cirrhosis is proved because all ascites is hepatic','Several nonhepatic processes cause ascites.'),('An isolated peritoneal malignancy explains the elevated JVP by definition','The venous signs point to an additional cardiac/systemic pressure question.'),('The JVP is irrelevant to the abdominal differential','It helps identify a congestive mechanism.')],
 'An abdominal finding can have a cardiac origin','**Systemic venous hypertension can produce hepatic congestion and ascites.**',['Cardiac and hepatic disease can coexist.','Fluid analysis and imaging refine the differential.'],'**Integrate cardiovascular and abdominal assessments.**',['Assess RV, valve and pericardial disease.','Do not infer the cause solely from the presence of liver stigmata.'],[['Ascites','Not always cirrhosis'],['High JVP','Cardiac congestion clue'],['Next step','Integrated hemodynamic/fluid assessment']],[AS],style='clinical_scenario')

q('A patient intermittently loses sustained wrist extension, producing a flapping appearance. Which statement about this sign is correct?', 'Asterixis is negative myoclonus and is not specific for hepatic encephalopathy',[
 ('It is a rhythmic resting tremor uniquely diagnostic of Parkinson disease','The mechanism and pattern differ.'),('It proves cirrhosis in every patient','Uremia, hypercapnia and drug effects are other causes.'),('Its absence excludes all metabolic encephalopathy','Sensitivity is limited and severe impairment can prevent testing.')],
 'Identify the movement mechanism','**Asterixis consists of brief lapses in sustained muscle activity.**',['Assess consciousness, respiratory state, kidney/liver function and drug exposure.','The sign can be asymmetric in selected focal disorders.'],'**Treat the underlying cause rather than the flapping itself.**',['Use the complete neurological and systemic examination.','Do not diagnose hepatic encephalopathy from asterixis alone.'],[['Mechanism','Negative myoclonus'],['Common contexts','Metabolic/toxic states'],['Specificity','Not liver-specific']],[AB])
